using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
public sealed class NotePage {public string id="",title="",project="",body="",updated="";public bool trashed=false;}
public sealed class ProjectSpace {public long budgetCents;public string launchModeId="";public string icon="";public ProjectFile cover;public List<ProjectBlock> blocks=ProjectVisuals.Defaults();public string name="",description="";public List<QuickLink> links=new List<QuickLink>();public List<ProjectFile> files=new List<ProjectFile>();}
public sealed class ProjectFile {public string id="",name="",extension="";}
internal static class ProjectData {
 internal static void Validate(Data d){if(d.pages==null)d.pages=new List<NotePage>();if(d.projectData==null)d.projectData=new List<ProjectSpace>();if(d.pages.Count>10000||d.projectData.Count>200)throw new InvalidDataException("Trop de pages ou de projets.");var ids=new HashSet<string>();foreach(var n in d.pages){if(n==null||String.IsNullOrWhiteSpace(n.title)||n.title.Length>200||(n.body??"").Length>300000||(n.project??"").Length>80)throw new InvalidDataException("Page invalide.");if(String.IsNullOrEmpty(n.id)||!ids.Add(n.id)){n.id=Guid.NewGuid().ToString();ids.Add(n.id);}n.body=n.body??"";n.project=n.project??"";}foreach(var p in d.projectData){if(p==null||String.IsNullOrWhiteSpace(p.name)||p.name.Length>80||(p.description??"").Length>10000)throw new InvalidDataException("Projet invalide.");if(p.links==null)p.links=new List<QuickLink>();if(p.files==null)p.files=new List<ProjectFile>();foreach(var l in p.links){Uri u;if(l==null||String.IsNullOrWhiteSpace(l.Name)||!Uri.TryCreate(l.Url,UriKind.Absolute,out u)||(u.Scheme!="http"&&u.Scheme!="https"))throw new InvalidDataException("Lien de projet invalide.");}foreach(var f in p.files)CheckFile(f);}}
 internal static ProjectSpace Get(Data d,string name){var p=d.projectData.FirstOrDefault(v=>v.name==name);if(p==null){p=new ProjectSpace{name=name};d.projectData.Add(p);}return p;}
 internal static void CheckFile(ProjectFile f){Guid id;if(f==null||!Guid.TryParse(f.id,out id)||String.IsNullOrWhiteSpace(f.name)||f.extension==null||f.extension.Length>14||(f.extension.Length>0&&(f.extension[0]!='.'||f.extension.Skip(1).Any(c=>!Char.IsLetterOrDigit(c)))))throw new InvalidDataException("Pièce jointe invalide.");}
 internal static string PathFor(Store s,ProjectFile f){CheckFile(f);return Path.Combine(s.Root,"Attachments",f.id+f.extension);}
 internal static ProjectFile Attach(Store s,string path){if(new FileInfo(path).Length>50L*1024*1024)throw new InvalidDataException("Limite : 50 Mo par fichier.");var f=new ProjectFile{id=Guid.NewGuid().ToString(),name=Path.GetFileName(path),extension=Path.GetExtension(path)};var target=PathFor(s,f);string folder=Path.GetDirectoryName(target);Directory.CreateDirectory(folder);string pending=Path.Combine(folder,".pending-"+Guid.NewGuid().ToString("N"));try{using(var source=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.Read))using(var output=new FileStream(pending,FileMode.CreateNew,FileAccess.Write,FileShare.None)){var buffer=new byte[81920];int count;long total=0;while((count=source.Read(buffer,0,buffer.Length))>0){total+=count;if(total>50L*1024*1024)throw new InvalidDataException("Limite : 50 Mo par fichier.");output.Write(buffer,0,count);}}File.Move(pending,target);return f;}catch{if(File.Exists(pending))File.Delete(pending);throw;}}
 internal static void Test(Store s,string folder){s.Value.pages.Add(new NotePage{id="test-note",title="Test",project="Test projet",body="# Titre\n- [ ] À faire"});Get(s.Value,"Test projet").description="Description";s.Save();var loaded=new Store(folder);if(!loaded.Value.pages.Any(n=>n.id=="test-note")||Get(loaded.Value,"Test projet").description!="Description")throw new Exception("Persistance des pages");string file=Path.Combine(folder,"attachment.txt");File.WriteAllText(file,"contenu");var f=Attach(s,file);if(File.ReadAllText(PathFor(s,f))!="contenu")throw new Exception("Copie pièce jointe");bool bad=false;try{PathFor(s,new ProjectFile{id="../outside",name="test",extension=".txt"});}catch(InvalidDataException){bad=true;}if(!bad)throw new Exception("Chemin non sécurisé");s.Export(Path.Combine(folder,"notes-export.json"));s.Value.pages.Clear();s.Import(Path.Combine(folder,"notes-export.json"));if(!s.Value.pages.Any())throw new Exception("Import pages");}
}
